<template>
  <section class="material-tracking-manager">
    <header class="mt-page-head">
      <div><span class="mt-eyebrow">ATLAS MATERIAL TRACKING</span><h2>Material Shipments</h2><p>Track every MEL line through partial shipment, transit, and delivery.</p></div>
      <div class="mt-head-actions"><button class="secondary-action" @click="emit('export')"><Download :size="16"/> Export Tracking Report</button><button v-if="canEdit" class="secondary-action" @click="emit('import')"><Upload :size="16"/> Import Tracking</button></div>
    </header>
    <p v-if="error" class="mt-error" role="alert">{{ error }}</p>

    <div class="mt-summary" aria-label="Material tracking summary">
      <button v-for="metric in summary" :key="metric.key" :class="{active:quick===metric.key}" @click="quick=quick===metric.key?'all':metric.key"><b>{{ metric.value }}</b><span>{{ metric.label }}</span></button>
    </div>

    <div class="mt-toolbar">
      <label class="mt-search"><Search :size="16"/><input v-model="search" type="search" placeholder="Search part, description, manufacturer, PO, vendor, tracking…"/></label>
      <select v-model="vendor"><option value="">All vendors</option><option v-for="value in vendors" :key="value">{{ value }}</option></select>
      <select v-model="manufacturer"><option value="">All manufacturers</option><option v-for="value in manufacturers" :key="value">{{ value }}</option></select>
      <select v-model="quoteFilter"><option value="">All Quotes / MELs</option><option v-for="value in quoteOptions" :key="value.id" :value="value.id">{{ value.label }}</option></select>
      <select v-model="status"><option value="">All statuses</option><option v-for="value in statuses" :key="value">{{ value }}</option></select>
      <button class="secondary-action" @click="clearFilters">Clear</button>
    </div>

    <div class="mt-quick"><button v-for="filter in quickFilters" :key="filter.key" :class="{active:quick===filter.key}" @click="quick=filter.key">{{ filter.label }}</button></div>

    <div v-if="canEdit && selected.size" class="mt-bulk"><b>{{ selected.size }} item{{selected.size===1?'':'s'}} selected across {{selectedMelCount}} MEL{{selectedMelCount===1?'':'s'}}</b><button class="primary-action" @click="openDelivery(allRows.filter(row=>selected.has(row.key)),'bulk')">Mark Selected as Delivered</button><button @click="openBulkShipment">Add Shipment</button><button @click="bulkEtaOpen=true">Update Expected Ship Date</button><button @click="selected.clear()">Clear Selection</button></div>

    <article class="mt-project">
      <button class="mt-project-head" @click="projectOpen=!projectOpen"><ChevronDown :class="{closed:!projectOpen}"/><div><h3>{{ project.projectNumber }} — {{ project.projectName }}</h3><p>Customer: {{ project.customer }}</p></div><span>{{ visibleRows.length }} visible MEL lines</span></button>
      <div v-if="projectOpen" class="mt-po-list">
        <article v-for="group in poGroups" :key="group.po.id" class="mt-po-group">
          <header><button @click="togglePo(group.po.id)"><ChevronDown :class="{closed:collapsedPos.has(group.po.id)}"/><span><b>{{ group.po.vendor }}</b><em>{{group.rows[0]?.quote.label}}</em><RouterLink :to="`/purchase-orders/${group.po.id}`" @click.stop>PO: {{ group.po.poNumber }}</RouterLink></span></button><p>{{ group.rows.length }} MEL Lines · {{ group.units }} Units · {{ group.shipped }} Shipped · {{ group.delivered }} Delivered · {{ group.needsTracking }} Need Tracking</p></header>
          <div v-if="!collapsedPos.has(group.po.id)" class="mt-table-wrap">
            <table><thead><tr><th><input type="checkbox" :checked="group.rows.every(row=>selected.has(row.key))" @change="toggleGroup(group.rows)"/></th><th>Line</th><th>Manufacturer</th><th>Part Number / Description</th><th>Qty Ordered</th><th>Qty Shipped</th><th>Status</th><th>Expected Ship</th><th>Carrier / Tracking</th><th>Delivery Action</th></tr></thead>
              <tbody><template v-for="row in group.rows" :key="row.key"><tr><td><input type="checkbox" :checked="selected.has(row.key)" @change="toggleSelected(row.key)"/></td><td>{{row.line.itemNumber||row.line.clin}}</td><td>{{row.line.manufacturer||'Pending'}}</td><td><b>{{row.line.partNumber||'No part number'}}</b><span>{{row.line.description}}</span></td><td>{{row.line.quantityOrdered}}</td><td><b>{{row.shipped}} / {{row.line.quantityOrdered}}</b><span>{{row.remaining}} remaining</span></td><td><span class="mt-status" :class="row.status.toLowerCase().replaceAll(' ','-')">{{row.status}}{{row.status==='Delivered'?' ✓':''}}</span><small v-if="row.late" class="mt-warning">Late</small><small v-if="row.needsTracking" class="mt-warning">Needs Tracking</small></td><td><input class="mt-date" type="date" :value="row.line.estimatedShipDate||''" @change="saveEta(row,($event.target as HTMLInputElement).value)"/></td><td><div v-if="row.shipments.length" class="mt-tracking"><span v-for="shipment in row.shipments.slice(-2)" :key="shipment.id"><b>{{shipment.carrier}}</b><a v-if="trackingUrl(shipment)" :href="trackingUrl(shipment)" target="_blank" rel="noopener">{{shipment.trackingNumber||'Tracking pending'}}</a><em>{{shipment.lines.find(item=>item.melLineItemId===row.line.id)?.quantityShipped}} units</em></span></div><button v-else class="mt-add" @click="openShipment(row)">+ Add Shipment</button></td><td><div class="mt-actions"><button v-if="row.status!=='Delivered'" class="primary-action" @click="openDelivery([row],'mark')">Mark Delivered</button><button v-else @click="openDelivery([row],'edit')">Delivered ✓ / Edit</button><button @click="openShipment(row)">Add Shipment</button><button @click="toggleHistory(row.key)">{{expanded.has(row.key)?'Hide':'View'}} Shipments</button></div></td></tr>
                <tr v-if="expanded.has(row.key)" class="mt-history-row"><td colspan="10"><section><header><h4>Shipment History</h4><span>{{row.shipped}} shipped / {{row.line.quantityOrdered}} ordered / {{row.remaining}} remaining</span></header><table v-if="row.shipments.length"><thead><tr><th>Qty</th><th>Ship Date</th><th>Carrier</th><th>Tracking</th><th>Expected Delivery</th><th>Delivered</th><th>Created By</th><th></th></tr></thead><tbody><tr v-for="shipment in row.shipments" :key="shipment.id"><td>{{shipment.lines.find(item=>item.melLineItemId===row.line.id)?.quantityShipped}}</td><td>{{date(shipment.actualShipDate)}}</td><td>{{shipment.carrier}}</td><td><a v-if="trackingUrl(shipment)" :href="trackingUrl(shipment)" target="_blank" rel="noopener">{{shipment.trackingNumber}}</a><span v-else>{{shipment.trackingNumber||'Pending'}}</span></td><td>{{date(shipment.expectedDeliveryDate)}}</td><td>{{date(shipment.lines.find(item=>item.melLineItemId===row.line.id)?.deliveredDate)}}</td><td>{{shipment.createdByName}}</td><td><div class="mt-actions"><button v-if="canEdit" @click="openEditShipment(shipment)">Edit Shipment</button><button v-if="!shipment.lines.find(item=>item.melLineItemId===row.line.id)?.deliveredDate" @click="deliver(shipment.id)">Mark Shipment Delivered</button></div></td></tr></tbody></table><p v-else>No shipments recorded.</p><div v-if="activities(row).length" class="mt-activity"><h4>Activity</h4><p v-for="activity in activities(row)" :key="activity.id"><time>{{dateTime(activity.occurredAt)}}</time><b>{{activity.action}}</b><span>{{activity.actorName}} · {{activity.newValue}}</span></p></div></section></td></tr></template></tbody>
            </table>
          </div>
        </article>
      </div>
    </article>

    <div v-if="drawerOpen" class="mt-drawer-shade" @click.self="closeDrawer">
      <aside class="mt-drawer" role="dialog" aria-modal="true" aria-labelledby="shipment-drawer-title">
        <header>
          <div><span id="shipment-drawer-title">{{editingShipmentId?'Edit Shipment':shipmentRows.length>1?'Bulk shipment':'Add shipment'}}</span><h3>{{shipmentRows.length===1?shipmentRows[0].line.partNumber:shipmentRows.length+' MEL lines'}}</h3><p>{{drawerPo?.poNumber}} · {{drawerPo?.vendor}}</p></div>
          <button :disabled="saving" aria-label="Close shipment details" @click="closeDrawer"><X/></button>
        </header>
        <form @submit.prevent="saveShipment">
          <div class="mt-context" v-if="shipmentRows.length===1"><span>Manufacturer <b>{{shipmentRows[0].line.manufacturer||'Pending'}}</b></span><span>Ordered <b>{{shipmentRows[0].line.quantityOrdered}}</b></span><span>Previously shipped <b>{{shipmentRows[0].shipped}}</b></span><span>Remaining <b>{{shipmentRows[0].remaining}}</b></span></div>
          <p v-if="editingShipmentId && shipmentRows.length>1" class="mt-shipment-note">This shipment covers {{shipmentRows.length}} MEL lines. Changes apply to every item listed below.</p>
          <label>Actual Ship Date *<input v-model="draft.actualShipDate" required type="date"/></label>
          <label>Carrier *<select v-model="draft.carrier" aria-label="Carrier" required><option value="">Select carrier</option><option v-for="item in carriers" :key="item">{{item}}</option></select></label>
          <label v-if="draft.carrier==='Other'">Carrier Name *<input v-model="draft.otherCarrier" required/></label>
          <label>Tracking Number<input v-model.trim="draft.trackingNumber" placeholder="Tracking number"/></label>
          <label>Expected Delivery Date<input v-model="draft.expectedDeliveryDate" type="date"/></label>
          <label>Packing Slip Number<input v-model.trim="draft.packingSlipNumber"/></label>
          <fieldset>
            <legend>{{editingShipmentId?'Items in this shipment':'Quantity in this shipment *'}}</legend>
            <div v-for="row in shipmentRows" :key="row.key">
              <span><b>{{row.line.partNumber}}</b>{{row.remaining}} remaining</span>
              <b v-if="editingShipmentId">{{draft.quantities[row.key]}} units</b>
              <input v-else v-model.number="draft.quantities[row.key]" :aria-label="'Quantity for '+row.line.partNumber" type="number" min="0.01" :max="row.remaining" step="0.01" required/>
            </div>
          </fieldset>
          <label>Shipment Notes<textarea v-model.trim="draft.notes" rows="3"/></label>
          <p v-if="error" class="mt-error" role="alert">{{error}}</p>
          <footer><button type="button" :disabled="saving" @click="closeDrawer">Cancel</button><button class="primary-action" type="submit" :disabled="saving">{{saving?'Saving…':editingShipmentId?'Save Changes':'Save Shipment'}}</button></footer>
        </form>
      </aside>
    </div>
    <div v-if="bulkEtaOpen" class="mt-modal-shade" @click.self="bulkEtaOpen=false"><form class="mt-modal" @submit.prevent="saveBulkEta"><h3>Update Expected Ship Date</h3><p>Apply one vendor ETA to {{selected.size}} selected MEL line{{selected.size===1?'':'s'}}.</p><input v-model="bulkEta" type="date" required/><footer><button type="button" @click="bulkEtaOpen=false">Cancel</button><button class="primary-action">Update ETA</button></footer></form></div>
    <div v-if="deliveryOpen" class="mt-modal-shade" @click.self="deliveryOpen=false"><form class="mt-modal mt-delivery-modal" @submit.prevent="confirmDelivery"><h3>{{deliveryMode==='edit'?'Edit Delivery':`Mark ${deliveryRows.length} item${deliveryRows.length===1?'':'s'} as delivered?`}}</h3><p v-for="row in deliveryRows" :key="row.key"><b>{{row.line.partNumber}}</b> — {{row.line.description}} · Qty {{row.line.quantityOrdered}} · {{row.quote.label}}</p><label>Delivered Date<input v-model="deliveryDate" type="date" required/></label><p>This explicitly confirms delivery. Carrier estimates never mark an item delivered.</p><footer><button v-if="deliveryMode==='edit'" class="danger" type="button" @click="reverseDelivery">Reverse Delivery</button><button type="button" @click="deliveryOpen=false">Cancel</button><button class="primary-action">{{deliveryMode==='edit'?'Save Delivery':'Confirm Delivered'}}</button></footer></form></div>
  </section>
</template>

<script setup lang="ts">
import {computed,reactive,ref} from 'vue'
import {ChevronDown,Download,Search,Upload,X} from '@lucide/vue'
import type {MaterialShipment,Project,PurchaseOrder,PurchaseOrderLine} from '../types'
import {fetchSession} from '../services/auth'
import {saveMaterialTrackingProject} from '../services/localProjects'
import {canManageMaterialTracking,carrierTrackingUrl,createMaterialShipment,customerMaterialStatus,editMaterialLineDeliveredDate,editMaterialShipment,isMaterialLineLate,lineQuantityRemaining,lineQuantityShipped,lineShipments,markMaterialLineDelivered,markMaterialShipmentDelivered,materialLineNeedsTracking,materialQuoteIdentity,reverseMaterialLineDelivery,updateMaterialExpectedShipDate,type CustomerMaterialStatus} from '../services/materialTracking'

const props=defineProps<{project:Project; deferSave?:boolean}>();const emit=defineEmits<{updated:[project:Project];import:[];export:[]}>()
type Row={key:string;po:PurchaseOrder;line:PurchaseOrderLine;quote:{id:string;label:string};status:CustomerMaterialStatus;late:boolean;needsTracking:boolean;shipped:number;remaining:number;shipments:MaterialShipment[]}
const search=ref(''),vendor=ref(''),manufacturer=ref(''),quoteFilter=ref(''),status=ref(''),quick=ref('all'),projectOpen=ref(true),collapsedPos=reactive(new Set<string>()),selected=reactive(new Set<string>()),expanded=reactive(new Set<string>()),drawerOpen=ref(false),shipmentRows=ref<Row[]>([]),saving=ref(false),error=ref(''),bulkEtaOpen=ref(false),bulkEta=ref(''),deliveryOpen=ref(false),deliveryRows=ref<Row[]>([]),deliveryDate=ref(new Date().toISOString().slice(0,10)),deliveryMode=ref<'mark'|'bulk'|'edit'>('mark')
const editingShipmentId=ref<string|null>(null)
const carriers=['UPS','FedEx','USPS','DHL','Freight / LTL','Local Delivery','Vendor Delivery','Other'];const statuses:CustomerMaterialStatus[]=['PO Issued','Processing','In Transit','Delivered'];const quickFilters=[{key:'needs',label:'Needs Tracking'},{key:'partial',label:'Partial Shipments'},{key:'transit',label:'In Transit'},{key:'delivered',label:'Delivered'},{key:'late',label:'Late'},{key:'all',label:'All Items'}]
const draft=reactive({carrier:'',otherCarrier:'',trackingNumber:'',actualShipDate:new Date().toISOString().slice(0,10),expectedDeliveryDate:'',packingSlipNumber:'',notes:'',quantities:{} as Record<string,number>})
const canEdit=computed(()=>canManageMaterialTracking(fetchSession()))
const allRows=computed<Row[]>(()=>props.project.purchaseOrders.flatMap(po=>{const identity=materialQuoteIdentity(props.project,po);return po.lines.map(line=>({key:`${po.id}:${line.id}`,po,line,quote:{id:identity.quoteId||`po:${po.id}`,label:identity.quoteName},status:customerMaterialStatus(props.project,po,line),late:isMaterialLineLate(props.project,po,line),needsTracking:materialLineNeedsTracking(props.project,po,line),shipped:lineQuantityShipped(props.project,po.id,line.id),remaining:lineQuantityRemaining(props.project,po.id,line.id),shipments:lineShipments(props.project,po.id,line.id)}))}))
const visibleRows=computed(()=>allRows.value.filter(row=>{const hay=[props.project.projectNumber,props.project.projectName,props.project.customer,row.quote.label,row.po.poNumber,row.po.vendor,row.line.partNumber,row.line.description,row.line.manufacturer,...row.shipments.map(item=>item.trackingNumber)].join(' ').toLowerCase();if(search.value&&!hay.includes(search.value.toLowerCase()))return false;if(vendor.value!==''&&row.po.vendor!==vendor.value)return false;if(manufacturer.value!==''&&row.line.manufacturer!==manufacturer.value)return false;if(quoteFilter.value!==''&&row.quote.id!==quoteFilter.value)return false;if(status.value!==''&&row.status!==status.value)return false;if(quick.value==='po-issued'&&row.status!=='PO Issued')return false;if(quick.value==='processing'&&row.status!=='Processing')return false;if(quick.value==='needs'&&!row.needsTracking)return false;if(quick.value==='partial'&&!(row.shipped>0&&row.remaining>0))return false;if(quick.value==='transit'&&row.status!=='In Transit')return false;if(quick.value==='delivered'&&row.status!=='Delivered')return false;if(quick.value==='late'&&!row.late)return false;return true}))
const poGroups=computed(()=>props.project.purchaseOrders.map(po=>{const rows=visibleRows.value.filter(row=>row.po.id===po.id);return{po,rows,units:rows.reduce((n,row)=>n+row.line.quantityOrdered,0),shipped:rows.filter(row=>row.shipped>0).length,delivered:rows.filter(row=>row.status==='Delivered').length,needsTracking:rows.filter(row=>row.needsTracking).length}}).filter(group=>group.rows.length))
const vendors=computed(()=>[...new Set(allRows.value.map(row=>row.po.vendor).filter(Boolean))].sort()),manufacturers=computed(()=>[...new Set(allRows.value.map(row=>row.line.manufacturer||'').filter(Boolean))].sort()),quoteOptions=computed(()=>[...new Map(allRows.value.map(row=>[row.quote.id,row.quote])).values()])
const summary=computed(()=>[{key:'all',label:'MEL Lines',value:allRows.value.length},{key:'po-issued',label:'PO Issued',value:allRows.value.filter(row=>row.status==='PO Issued').length},{key:'processing',label:'Processing',value:allRows.value.filter(row=>row.status==='Processing').length},{key:'transit',label:'In Transit',value:allRows.value.filter(row=>row.status==='In Transit').length},{key:'delivered',label:'Delivered',value:allRows.value.filter(row=>row.status==='Delivered').length},{key:'late',label:'Late',value:allRows.value.filter(row=>row.late).length}])
const selectedMelCount=computed(()=>new Set(allRows.value.filter(row=>selected.has(row.key)).map(row=>row.quote.id)).size)
const drawerPo=computed(()=>shipmentRows.value[0]?.po)
function actor(){return fetchSession()||{id:'atlas-user',name:'Atlas User'}}async function commit(project:Project){if(saving.value)return false;saving.value=true;error.value='';try{const saved=props.deferSave?project:await saveMaterialTrackingProject(project,props.project);emit('updated',saved);return true}catch(reason){error.value=reason instanceof Error?reason.message:'Tracking could not be saved.';return false}finally{saving.value=false}}function clearFilters(){search.value='';vendor.value='';manufacturer.value='';quoteFilter.value='';status.value='';quick.value='all'}function togglePo(id:string){collapsedPos.has(id)?collapsedPos.delete(id):collapsedPos.add(id)}function toggleSelected(key:string){selected.has(key)?selected.delete(key):selected.add(key)}function toggleGroup(rows:Row[]){const all=rows.every(row=>selected.has(row.key));rows.forEach(row=>all?selected.delete(row.key):selected.add(row.key))}function toggleHistory(key:string){expanded.has(key)?expanded.delete(key):expanded.add(key)}
function resetDraft(){editingShipmentId.value=null;Object.assign(draft,{carrier:'',otherCarrier:'',trackingNumber:'',actualShipDate:new Date().toISOString().slice(0,10),expectedDeliveryDate:'',packingSlipNumber:'',notes:'',quantities:{}});error.value=''}
function openShipment(row:Row){resetDraft();shipmentRows.value=[row];draft.quantities[row.key]=row.remaining;drawerOpen.value=true}
function openBulkShipment(){const rows=allRows.value.filter(row=>selected.has(row.key)&&row.remaining>0);const poIds=new Set(rows.map(row=>row.po.id));if(poIds.size!==1){window.alert('Bulk shipments must contain MEL lines from the same purchase order and vendor.');return}resetDraft();shipmentRows.value=rows;rows.forEach(row=>draft.quantities[row.key]=row.remaining);drawerOpen.value=true}
function openEditShipment(shipment:MaterialShipment){
  if(!canEdit.value||saving.value)return
  resetDraft()
  editingShipmentId.value=shipment.id
  shipmentRows.value=allRows.value.filter(row=>row.po.id===shipment.poId&&shipment.lines.some(item=>item.melLineItemId===row.line.id))
  const knownCarrier=carriers.includes(shipment.carrier)&&shipment.carrier!=='Other'
  Object.assign(draft,{carrier:knownCarrier?shipment.carrier:'Other',otherCarrier:knownCarrier?'':shipment.carrier,trackingNumber:shipment.trackingNumber,actualShipDate:shipment.actualShipDate,expectedDeliveryDate:shipment.expectedDeliveryDate||'',packingSlipNumber:shipment.packingSlipNumber||'',notes:shipment.notes||''})
  shipmentRows.value.forEach(row=>draft.quantities[row.key]=shipment.lines.filter(item=>item.melLineItemId===row.line.id).reduce((sum,item)=>sum+item.quantityShipped,0))
  drawerOpen.value=true
}
function closeDrawer(){if(saving.value)return;drawerOpen.value=false;shipmentRows.value=[];editingShipmentId.value=null}
async function saveShipment(){
  const po=drawerPo.value
  if(!po||saving.value)return
  error.value=''
  try{
    const details={carrier:draft.carrier,otherCarrier:draft.otherCarrier,trackingNumber:draft.trackingNumber,actualShipDate:draft.actualShipDate,expectedDeliveryDate:draft.expectedDeliveryDate,packingSlipNumber:draft.packingSlipNumber,notes:draft.notes}
    const project=editingShipmentId.value
      ?editMaterialShipment(props.project,editingShipmentId.value,details,actor())
      :createMaterialShipment(props.project,{...details,poId:po.id,lines:shipmentRows.value.map(row=>({poId:po.id,melLineItemId:row.line.id,quantity:Number(draft.quantities[row.key])}))},actor())
    if(project!==props.project&&!await commit(project))return
    selected.clear()
    closeDrawer()
  }catch(reason){error.value=reason instanceof Error?reason.message:'Unable to save shipment.'}
}
async function saveEta(row:Row,value:string){await commit(updateMaterialExpectedShipDate(props.project,row.po.id,row.line.id,value,actor()))}async function saveBulkEta(){let project=props.project;allRows.value.filter(row=>selected.has(row.key)).forEach(row=>{project=updateMaterialExpectedShipDate(project,row.po.id,row.line.id,bulkEta.value,actor())});if(!await commit(project))return;bulkEtaOpen.value=false;selected.clear()}async function deliver(id:string){const value=window.prompt('Delivered date (YYYY-MM-DD)',new Date().toISOString().slice(0,10));if(value)await commit(markMaterialShipmentDelivered(props.project,id,value,actor()))}function trackingUrl(shipment:MaterialShipment){return carrierTrackingUrl(shipment.carrier,shipment.trackingNumber)}function activities(row:Row){return(props.project.materialTrackingActivity||[]).filter(item=>item.melLineItemId===row.line.id).sort((a,b)=>b.occurredAt.localeCompare(a.occurredAt)).slice(0,12)}function date(value?:string){return value?new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric'}).format(new Date(`${value.slice(0,10)}T12:00:00`)):'—'}function dateTime(value:string){return new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(value))}
function openDelivery(rows:Row[],mode:'mark'|'bulk'|'edit'){deliveryRows.value=rows;deliveryMode.value=mode;const existing=rows[0]?.shipments.flatMap(shipment=>shipment.lines).find(item=>item.melLineItemId===rows[0]?.line.id&&item.deliveredDate)?.deliveredDate;deliveryDate.value=existing||new Date().toISOString().slice(0,10);deliveryOpen.value=true}async function confirmDelivery(){let project=props.project;for(const row of deliveryRows.value)project=deliveryMode.value==='edit'?editMaterialLineDeliveredDate(project,row.po.id,row.line.id,deliveryDate.value,actor()):markMaterialLineDelivered(project,row.po.id,row.line.id,deliveryDate.value,actor());if(!await commit(project))return;deliveryOpen.value=false;selected.clear()}async function reverseDelivery(){let project=props.project;for(const row of deliveryRows.value)project=reverseMaterialLineDelivery(project,row.po.id,row.line.id,actor());if(!await commit(project))return;deliveryOpen.value=false;selected.clear()}
